import{f as a,o,c as i,a2 as r}from"./chunks/framework.Cd9rfTEn.js";const g=JSON.parse('{"title":"Complemento de análisis funcional y diseño del sistema de cooperativas","description":"","frontmatter":{},"headers":[],"relativePath":"base-funcional/PROCOOP_COMPLEMENTO_ANALISIS_FUNCIONAL_Y_DISENO.md","filePath":"base-funcional/PROCOOP_COMPLEMENTO_ANALISIS_FUNCIONAL_Y_DISENO.md","lastUpdated":null}'),n={name:"base-funcional/PROCOOP_COMPLEMENTO_ANALISIS_FUNCIONAL_Y_DISENO.md"};function t(s,e,c,d,l,p){return o(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="complemento-de-analisis-funcional-y-diseno-del-sistema-de-cooperativas" tabindex="-1">Complemento de análisis funcional y diseño del sistema de cooperativas <a class="header-anchor" href="#complemento-de-analisis-funcional-y-diseno-del-sistema-de-cooperativas" aria-label="Permalink to &quot;Complemento de análisis funcional y diseño del sistema de cooperativas&quot;">​</a></h1><p>Versión: 0.1<br> Fecha: 3 de noviembre de 2026<br> Documento base revisado: PROCOOP_RELEVAMIENTO_Y_BASE_FUNCIONAL.md, versión 0.14.<br> Estado: propuestas del análisis, pendientes de validación e incorporación al alcance aprobado.</p><h2 id="_1-proposito-y-criterio-de-revision" tabindex="-1">1. Propósito y criterio de revisión <a class="header-anchor" href="#_1-proposito-y-criterio-de-revision" aria-label="Permalink to &quot;1. Propósito y criterio de revisión&quot;">​</a></h2><p>Este documento adicional identifica aspectos que conviene incorporar o precisar para convertir la visión del sistema en una especificación desarrollable y operable. Se revisó el documento base completo, sus 96 secciones numeradas, ampliaciones, fuentes y anexo de 20 mensajes originales. La base se conserva sin cambios.</p><p>El foco es el producto definido: SaaS multitenant de gestión cooperativa con ERP, CRM, comunidad, autogestión, servicios configurables, facturación argentina y operación técnica. No se proponen módulos ajenos a esa visión ni se convierte cada posibilidad en requisito obligatorio.</p><p>Se distinguen tres diagnósticos:</p><ul><li><strong>No explicitado:</strong> no se encontró un circuito o requisito expreso equivalente en la base. No significa que no pueda estar implícito en una categoría general.</li><li><strong>Detalle insuficiente:</strong> el tema existe; faltan decisiones, reglas o criterios para implementarlo sin ambigüedad.</li><li><strong>Pendiente ya identificado:</strong> la base ya lo dejó abierto. El aporte aquí es proponer cómo cerrarlo, no presentarlo como un descubrimiento nuevo.</li></ul><p>Las prioridades son de análisis, no de implementación completa:</p><ul><li><strong>P0:</strong> resolver la decisión o contrato funcional antes de cerrar arquitectura o construir el núcleo. No exige construir toda la función en la primera entrega.</li><li><strong>P1:</strong> concretar antes de poner en producción el flujo afectado; imprescindible si se incluye en el piloto.</li><li><strong>P2:</strong> decidir su inclusión y momento; puede diferirse con límites explícitos.</li></ul><p>Todas las recomendaciones de este complemento son propuestas. Los requisitos informados por el solicitante conservan su condición en la base; ninguna propuesta se considera aprobada por aparecer aquí.</p><h2 id="_2-diagnostico-principal" tabindex="-1">2. Diagnóstico principal <a class="header-anchor" href="#_2-diagnostico-principal" aria-label="Permalink to &quot;2. Diagnóstico principal&quot;">​</a></h2><p>La base tiene una cobertura funcional amplia: los módulos principales y las particularidades de servicios ya están relevados. El mayor trabajo pendiente no consiste en agregar nombres de módulos, sino en definir cómo funcionan sus bordes: quién puede actuar, qué dato es la fuente, cuándo cambia el estado, cómo se reintenta, cómo se corrige y cómo se concilian los efectos económicos.</p><p>Los puntos más determinantes para arquitectura son el modelo de identidad multitenant, los responsables de los datos, los estados y eventos entre módulos, el historial con fechas efectivas, la integridad de saldos y la publicación de configuración. Si se resuelven tarde, obligarán a rehacer contratos de API, pantallas, procesos y migraciones.</p><p>Los vacíos operativos más visibles son el circuito de pagos excedentes/no identificados y la moderación de comunidad si se habilita participación. Otros puntos —migración, backups, presupuestos, activos, privacidad y soporte— ya están mencionados, pero necesitan definición para ser comprobables.</p><h3 id="_2-1-que-ya-esta-y-no-hace-falta-volver-a-inventar" tabindex="-1">2.1. Qué ya está y no hace falta volver a inventar <a class="header-anchor" href="#_2-1-que-ya-esta-y-no-hace-falta-volver-a-inventar" aria-label="Permalink to &quot;2.1. Qué ya está y no hace falta volver a inventar&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Capacidad cubierta en la base</th><th>Referencias</th><th>Aporte necesario del complemento</th></tr></thead><tbody><tr><td>Tenants, roles, perfiles, marca y diccionario</td><td>42–45, 60, 65</td><td>Cerrar reglas efectivas, ciclo del tenant y publicación.</td></tr><tr><td>Catálogo de servicios y copia entre cooperativas</td><td>66, 72, 81, 84</td><td>Convertir copia en paquete validable y mantener dependencias.</td></tr><tr><td>Facturación, cuenta corriente, cobranza y tesorería</td><td>10–14, 21–22, 44, 68–69, 75</td><td>Definir invariantes, correcciones, excedentes y cierre.</td></tr><tr><td>ERP con cuentas y centros de costos reales/simulados</td><td>55, 75</td><td>Completar controles operativos y opciones de activos/presupuesto.</td></tr><tr><td>CRM, IA, chat, bot y supervisión</td><td>47</td><td>Estados, responsabilidad y evaluación de automatizaciones.</td></tr><tr><td>Visitas, equipo, firma, encuesta y primer cobro</td><td>50, 73</td><td>Concurrencia, contingencia offline y efectos parciales.</td></tr><tr><td>APIs, seguridad, auditoría y organismos fiscales</td><td>54, 59–62</td><td>Contratos operativos, entornos y evidencia de verificación.</td></tr><tr><td>Seis dominios y límites regulatorios</td><td>85–95</td><td>Obtener documentación real y cerrar reglas por cooperativa.</td></tr></tbody></table><h2 id="_3-matriz-de-propuestas-y-trazabilidad" tabindex="-1">3. Matriz de propuestas y trazabilidad <a class="header-anchor" href="#_3-matriz-de-propuestas-y-trazabilidad" aria-label="Permalink to &quot;3. Matriz de propuestas y trazabilidad&quot;">​</a></h2><p>La referencia a secciones corresponde siempre al documento base v0.14. Los identificadores AGR son propios de este complemento y no reutilizan los IDs de requisitos originales.</p><table tabindex="0"><thead><tr><th>ID</th><th>Propuesta</th><th>Prioridad</th><th>Diagnóstico respecto de la base</th><th>Secciones base</th></tr></thead><tbody><tr><td>AGR-001</td><td>Consolidar requisitos y decisiones en un catálogo único</td><td>P0</td><td>Detalle insuficiente</td><td>2, 34–38, 84, 93, 96</td></tr><tr><td>AGR-002</td><td>Responsable de cada dato y límite entre ERP, CRM y operación</td><td>P0</td><td>Pendiente ya identificado</td><td>33, 58, 73, 75, 78, 84</td></tr><tr><td>AGR-003</td><td>Modelos de estados y reversión por proceso</td><td>P0</td><td>Detalle insuficiente</td><td>15–17, 39, 47–50, 53, 69, 73</td></tr><tr><td>AGR-004</td><td>Ciclo de vida completo de la cooperativa y preparación para producción</td><td>P0</td><td>Detalle insuficiente</td><td>42–43, 64, 66, 81</td></tr><tr><td>AGR-005</td><td>Contrato comercial SaaS y habilitación de capacidades</td><td>P2</td><td>Pendiente ya identificado</td><td>64, 66, 81</td></tr><tr><td>AGR-006</td><td>Identidad de acceso, pertenencia y selección de cooperativa</td><td>P0</td><td>Pendiente ya identificado</td><td>3, 42, 59–60, 67, 83</td></tr><tr><td>AGR-007</td><td>Representaciones, titulares, beneficiarios y cambios de responsabilidad</td><td>P1</td><td>Detalle insuficiente</td><td>3–4, 24, 67, 83, 90–91</td></tr><tr><td>AGR-008</td><td>Regla exacta de combinación entre roles y perfiles</td><td>P0</td><td>Pendiente ya identificado</td><td>29, 42, 45, 60</td></tr><tr><td>AGR-009</td><td>Publicación segura de configuración y paquetes de servicio</td><td>P0</td><td>Detalle insuficiente</td><td>6, 51, 65–66, 72, 81</td></tr><tr><td>AGR-010</td><td>Historia con fecha efectiva y fecha de registro</td><td>P0</td><td>Detalle insuficiente</td><td>4, 6–11, 51, 55, 69, 75, 83</td></tr><tr><td>AGR-011</td><td>Invariantes monetarias y única fuente del saldo</td><td>P0</td><td>Detalle insuficiente</td><td>10–14, 22, 40, 44, 51, 55, 75, 78</td></tr><tr><td>AGR-012</td><td>Pagos excedentes, anticipos y cobros sin identificar</td><td>P1</td><td>No explicitado</td><td>11–13, 40, 44, 68, 75</td></tr><tr><td>AGR-013</td><td>Devoluciones y reversos con sus dos efectos</td><td>P1</td><td>Detalle insuficiente</td><td>10–14, 21–22, 53, 61, 75</td></tr><tr><td>AGR-014</td><td>Vida completa de convenios y financiación</td><td>P1</td><td>Detalle insuficiente</td><td>14, 23, 51, 68, 72</td></tr><tr><td>AGR-015</td><td>Cierre y aprobación de cada ciclo de facturación</td><td>P0</td><td>Detalle insuficiente</td><td>10, 51, 69, 75</td></tr><tr><td>AGR-016</td><td>Ejecución fiable de acciones entre componentes</td><td>P0</td><td>Detalle insuficiente</td><td>13, 47, 54, 58–59, 61, 69, 73</td></tr><tr><td>AGR-017</td><td>Calendarios, prorrateos y cambios dentro del período</td><td>P1</td><td>Detalle insuficiente</td><td>6, 51, 69, 72–73</td></tr><tr><td>AGR-018</td><td>Migración y cambio operativo desde el sistema anterior</td><td>P1</td><td>Detalle insuficiente</td><td>31, 35, 64, 95</td></tr><tr><td>AGR-019</td><td>Recuperación y restauración por tenant</td><td>P0</td><td>Detalle insuficiente</td><td>29, 54, 60, 64</td></tr><tr><td>AGR-020</td><td>Capacidad, rendimiento y aislamiento de carga</td><td>P0</td><td>Pendiente ya identificado</td><td>54, 58–60, 64, 69</td></tr><tr><td>AGR-021</td><td>Operación de APIs y conectores, además de su desarrollo</td><td>P1</td><td>Detalle insuficiente</td><td>13, 31, 59, 61, 79</td></tr><tr><td>AGR-022</td><td>Contrato semántico para dashboards y BI</td><td>P1</td><td>Detalle insuficiente</td><td>30, 54–55, 59, 75</td></tr><tr><td>AGR-023</td><td>Expediente documental y conservación de evidencia</td><td>P1</td><td>Detalle insuficiente</td><td>3, 17, 43, 47, 54, 61, 73, 90–91</td></tr><tr><td>AGR-024</td><td>Comunicaciones, entrega y constancias</td><td>P1</td><td>Detalle insuficiente</td><td>26, 43, 47, 50, 52–54, 73</td></tr><tr><td>AGR-025</td><td>Visitas y operación sin conexión con conflictos</td><td>P1</td><td>Detalle insuficiente</td><td>8, 17, 50, 73, 77</td></tr><tr><td>AGR-026</td><td>Valorización, activos y reparación de equipos</td><td>P1</td><td>Pendiente ya identificado</td><td>7, 18, 20, 55, 73, 75, 78</td></tr><tr><td>AGR-027</td><td>Control de compra, recepción y factura de proveedor</td><td>P1</td><td>Detalle insuficiente</td><td>19–21, 61, 75, 78</td></tr><tr><td>AGR-028</td><td>Presupuestos y compromisos de fondos</td><td>P2</td><td>Pendiente ya identificado</td><td>19, 21–22, 55, 75</td></tr><tr><td>AGR-029</td><td>Capital y relación institucional del asociado</td><td>P1</td><td>Pendiente ya identificado</td><td>3, 27, 75, 83</td></tr><tr><td>AGR-030</td><td>Gobierno de la IA y verificación de sus resultados</td><td>P0</td><td>Detalle insuficiente</td><td>47, 54, 60, 65, 73, 91</td></tr><tr><td>AGR-031</td><td>Moderación y ciclo de vida de la comunidad</td><td>P2</td><td>No explicitado</td><td>26, 46, 65, 82</td></tr><tr><td>AGR-032</td><td>Accesibilidad y autogestión tolerante a errores</td><td>P1</td><td>Detalle insuficiente</td><td>25, 43, 50, 60, 65, 67, 73</td></tr><tr><td>AGR-033</td><td>Ciclo de privacidad, conservación y salida de datos</td><td>P0</td><td>Detalle insuficiente</td><td>29, 54, 59–60, 64, 77, 83, 90–91</td></tr><tr><td>AGR-034</td><td>Soporte con acceso temporal y responsabilidad</td><td>P1</td><td>Detalle insuficiente</td><td>42, 54, 60, 64</td></tr><tr><td>AGR-035</td><td>Entornos, pruebas y evidencias antes de cada entrega</td><td>P0</td><td>Detalle insuficiente</td><td>34, 39–40, 54–55, 60, 69, 73</td></tr><tr><td>AGR-036</td><td>Plan de entrega y aceptación de la cooperativa piloto</td><td>P0</td><td>Pendiente ya identificado</td><td>35, 37, 58, 64, 95</td></tr></tbody></table><h2 id="_4-fichas-de-ampliacion-recomendadas" tabindex="-1">4. Fichas de ampliación recomendadas <a class="header-anchor" href="#_4-fichas-de-ampliacion-recomendadas" aria-label="Permalink to &quot;4. Fichas de ampliación recomendadas&quot;">​</a></h2><p>Cada ficha contiene un problema concreto, una propuesta, un ejemplo y un criterio verificable. El criterio puede implementarse como prueba, inspección de diseño o evidencia operativa según corresponda.</p><h3 id="agr-001-—-consolidar-requisitos-y-decisiones-en-un-catalogo-unico" tabindex="-1">AGR-001 — Consolidar requisitos y decisiones en un catálogo único <a class="header-anchor" href="#agr-001-—-consolidar-requisitos-y-decisiones-en-un-catalogo-unico" aria-label="Permalink to &quot;AGR-001 — Consolidar requisitos y decisiones en un catálogo único&quot;">​</a></h3><p><strong>Prioridad:</strong> P0. <strong>Diagnóstico:</strong> Detalle insuficiente. <strong>Base:</strong> secciones 2, 34–38, 84, 93, 96.</p><p><strong>Qué falta concretar y por qué:</strong> La base acumuló ampliaciones y pendientes a lo largo de 96 secciones. Tener todos los textos no asegura que cada decisión tenga una única versión vigente y responsable.</p><p><strong>Propuesta:</strong> Crear un registro con ID estable, origen, redacción vigente, estado —informado, propuesto, aprobado, rechazado o sustituido—, responsable, dependencia, versión y criterio de aceptación. Referenciar los mensajes P-001 a P-020 sin convertir todas las opiniones del anexo en hechos verificados. Mantener ejemplos fuera de la configuración normativa.</p><p><strong>Ejemplo:</strong> Una regla propuesta en una sección y precisada después debe mostrar cuál redacción prevalece y qué decisión la sustituyó.</p><p><strong>Criterio de aceptación:</strong> Cada requisito del piloto tiene una definición vigente identificable y puede rastrearse a su origen y prueba; una contradicción no se resuelve eligiendo arbitrariamente el párrafo más conveniente.</p><h3 id="agr-002-—-responsable-de-cada-dato-y-limite-entre-erp-crm-y-operacion" tabindex="-1">AGR-002 — Responsable de cada dato y límite entre ERP, CRM y operación <a class="header-anchor" href="#agr-002-—-responsable-de-cada-dato-y-limite-entre-erp-crm-y-operacion" aria-label="Permalink to &quot;AGR-002 — Responsable de cada dato y límite entre ERP, CRM y operación&quot;">​</a></h3><p><strong>Prioridad:</strong> P0. <strong>Diagnóstico:</strong> Pendiente ya identificado. <strong>Base:</strong> secciones 33, 58, 73, 75, 78, 84.</p><p><strong>Qué falta concretar y por qué:</strong> La revisión de arquitectura está expresamente pedida, pero falta convertirla en un mapa de propietarios de datos y comandos. Varias pantallas podrían terminar modificando el mismo estado.</p><p><strong>Propuesta:</strong> Asignar un responsable funcional a persona, vínculo de tenant, contrato, visita, instalación, medición, factura, pago y asiento. Los otros módulos solicitan acciones o consultan proyecciones; no escriben directamente estados ajenos. Definir comandos, eventos y resultados esperados.</p><p><strong>Ejemplo:</strong> CRM puede solicitar una baja y mostrar su avance; el componente contractual confirma el cambio efectivo y facturación calcula las consecuencias.</p><p><strong>Criterio de aceptación:</strong> Para cada entidad crítica hay un responsable y una interfaz de modificación documentados; cerrar un ticket por sí solo no cambia un contrato ni cancela deuda.</p><h3 id="agr-003-—-modelos-de-estados-y-reversion-por-proceso" tabindex="-1">AGR-003 — Modelos de estados y reversión por proceso <a class="header-anchor" href="#agr-003-—-modelos-de-estados-y-reversion-por-proceso" aria-label="Permalink to &quot;AGR-003 — Modelos de estados y reversión por proceso&quot;">​</a></h3><p><strong>Prioridad:</strong> P0. <strong>Diagnóstico:</strong> Detalle insuficiente. <strong>Base:</strong> secciones 15–17, 39, 47–50, 53, 69, 73.</p><p><strong>Qué falta concretar y por qué:</strong> Ya existen estados de ejemplo, pero no tablas completas de transiciones, responsables, precondiciones y efectos. Dos procesos pueden quedar en estados incompatibles.</p><p><strong>Propuesta:</strong> Definir por proceso estado origen/destino, actor, requisitos, datos obligatorios, efectos, avisos, reversión y tratamiento de cancelación. Distinguir el estado del trámite del estado real del contrato, equipo, pago y documento.</p><p><strong>Ejemplo:</strong> Cancelar una visita no cancela necesariamente la contratación; anular una solicitud antes de instalar no debe exigir el circuito de retiro de un equipo instalado.</p><p><strong>Criterio de aceptación:</strong> Toda transición aceptada o rechazada puede explicarse por una regla; no existe edición libre de Activo, Pagado o Emitido para forzar cierres.</p><h3 id="agr-004-—-ciclo-de-vida-completo-de-la-cooperativa-y-preparacion-para-produccion" tabindex="-1">AGR-004 — Ciclo de vida completo de la cooperativa y preparación para producción <a class="header-anchor" href="#agr-004-—-ciclo-de-vida-completo-de-la-cooperativa-y-preparacion-para-produccion" aria-label="Permalink to &quot;AGR-004 — Ciclo de vida completo de la cooperativa y preparación para producción&quot;">​</a></h3><p><strong>Prioridad:</strong> P0. <strong>Diagnóstico:</strong> Detalle insuficiente. <strong>Base:</strong> secciones 42–43, 64, 66, 81.</p><p><strong>Qué falta concretar y por qué:</strong> Se contempla el alta del tenant, pero faltan etapas operativas de preparación, validación, habilitación, suspensión administrativa, reactivación y salida.</p><p><strong>Propuesta:</strong> Proponer estados Preparación, Prueba, Listo para habilitar, Operativo y Cierre administrativo, con tareas por área. Exigir checklist de identidad, servicio, tarifas, emisión, pagos, usuarios, contactos y saldos iniciales para cada capacidad productiva. Diferenciar disponibilidad técnica, situación comercial SaaS y prestación al socio.</p><p><strong>Ejemplo:</strong> Un tenant puede cargar marca y catálogo mientras todavía no tiene credenciales fiscales aprobadas; eso no debe habilitar emisión real.</p><p><strong>Criterio de aceptación:</strong> No se activa una capacidad productiva con datos de demostración o dependencias faltantes; una decisión administrativa de plataforma no ejecuta bajas masivas de servicios de la cooperativa.</p><h3 id="agr-005-—-contrato-comercial-saas-y-habilitacion-de-capacidades" tabindex="-1">AGR-005 — Contrato comercial SaaS y habilitación de capacidades <a class="header-anchor" href="#agr-005-—-contrato-comercial-saas-y-habilitacion-de-capacidades" aria-label="Permalink to &quot;AGR-005 — Contrato comercial SaaS y habilitación de capacidades&quot;">​</a></h3><p><strong>Prioridad:</strong> P2. <strong>Diagnóstico:</strong> Pendiente ya identificado. <strong>Base:</strong> secciones 64, 66, 81.</p><p><strong>Qué falta concretar y por qué:</strong> La base declara que precio y licenciamiento SaaS no están definidos. Conviene diseñar el punto de conexión sin inventar todavía el modelo comercial.</p><p><strong>Propuesta:</strong> Separar capacidades contratadas a la plataforma, servicios ofrecidos por el tenant y contratos de sus socios. Si se comercializa por módulos o cupos, definir vigencia, límites blandos/duros, excedentes, avisos y tratamiento de baja del cliente SaaS. Determinar acceso a documentos y exportación durante una transición.</p><p><strong>Ejemplo:</strong> Deshabilitar nuevas contrataciones de un módulo no debe ocultar facturas históricas del tenant ni eliminar expedientes.</p><p><strong>Criterio de aceptación:</strong> El sistema puede explicar qué habilitación depende del producto SaaS y cuál del catálogo del tenant; no se implementa un precio o límite sin decisión comercial expresa.</p><h3 id="agr-006-—-identidad-de-acceso-pertenencia-y-seleccion-de-cooperativa" tabindex="-1">AGR-006 — Identidad de acceso, pertenencia y selección de cooperativa <a class="header-anchor" href="#agr-006-—-identidad-de-acceso-pertenencia-y-seleccion-de-cooperativa" aria-label="Permalink to &quot;AGR-006 — Identidad de acceso, pertenencia y selección de cooperativa&quot;">​</a></h3><p><strong>Prioridad:</strong> P0. <strong>Diagnóstico:</strong> Pendiente ya identificado. <strong>Base:</strong> secciones 3, 42, 59–60, 67, 83.</p><p><strong>Qué falta concretar y por qué:</strong> La identidad global o separada por tenant sigue abierta y afecta registro, Google, recuperaciones, duplicados y privacidad.</p><p><strong>Propuesta:</strong> Como hipótesis preferida, evaluar una identidad de acceso común con pertenencias privadas a tenants, manteniendo separados los registros de personas y asociados de cada cooperativa. La selección de ámbito debe ser explícita, comprobada en servidor y visible al usuario. La coincidencia de DNI o correo no concede pertenencia.</p><p><strong>Ejemplo:</strong> Una persona que trabaja en A y contrata un servicio en B cambia de ámbito sin mezclar sus roles ni revelar a una cooperativa su relación con la otra.</p><p><strong>Criterio de aceptación:</strong> Un cambio de tenant obliga a recalcular permisos y datos visibles, incluyendo descargas, caché, conversaciones y trabajos de fondo.</p><h3 id="agr-007-—-representaciones-titulares-beneficiarios-y-cambios-de-responsabilidad" tabindex="-1">AGR-007 — Representaciones, titulares, beneficiarios y cambios de responsabilidad <a class="header-anchor" href="#agr-007-—-representaciones-titulares-beneficiarios-y-cambios-de-responsabilidad" aria-label="Permalink to &quot;AGR-007 — Representaciones, titulares, beneficiarios y cambios de responsabilidad&quot;">​</a></h3><p><strong>Prioridad:</strong> P1. <strong>Diagnóstico:</strong> Detalle insuficiente. <strong>Base:</strong> secciones 3–4, 24, 67, 83, 90–91.</p><p><strong>Qué falta concretar y por qué:</strong> Los roles de persona están distinguidos, pero falta el ciclo verificable de autorización, vencimiento y revocación de representación y de los cambios de titularidad.</p><p><strong>Propuesta:</strong> Modelar relaciones con inicio/fin, alcance y evidencia. Definir quién puede consultar, pagar, solicitar baja o firmar por otro. Resolver fallecimiento, representación de organizaciones, grupo familiar y cambio de pagador sin reasignar deuda automáticamente. Conservar la responsabilidad de cada período.</p><p><strong>Ejemplo:</strong> Un hermano paga una factura del otro sin adquirir derecho a ver todos sus contratos; revocar una representación retira el acceso futuro.</p><p><strong>Criterio de aceptación:</strong> Cada gestión en nombre de tercero acredita una relación vigente para esa acción y conserva quién actuó y por quién.</p><h3 id="agr-008-—-regla-exacta-de-combinacion-entre-roles-y-perfiles" tabindex="-1">AGR-008 — Regla exacta de combinación entre roles y perfiles <a class="header-anchor" href="#agr-008-—-regla-exacta-de-combinacion-entre-roles-y-perfiles" aria-label="Permalink to &quot;AGR-008 — Regla exacta de combinación entre roles y perfiles&quot;">​</a></h3><p><strong>Prioridad:</strong> P0. <strong>Diagnóstico:</strong> Pendiente ya identificado. <strong>Base:</strong> secciones 29, 42, 45, 60.</p><p><strong>Qué falta concretar y por qué:</strong> Está clara la diferencia entre pantalla y función, pero falta resolver varios roles/perfiles, restricciones por sucursal/área, denegaciones y separación de tareas.</p><p><strong>Propuesta:</strong> Definir cómo se calcula el permiso efectivo, el alcance sobre datos y el tratamiento de conflictos. Proponer denegación por defecto, aprobación independiente para operaciones sensibles y pruebas de permiso por acción y objeto. Restringir la autoasignación de privilegios y el poder de delegarlos.</p><p><strong>Ejemplo:</strong> Ver Tesorería no permite aprobar una devolución propia; un supervisor de Agua no obtiene por ese rol los expedientes sanitarios de Banco de sangre.</p><p><strong>Criterio de aceptación:</strong> Para cualquier usuario se puede explicar por qué una pantalla, registro y acción están habilitados o denegados, también en la API.</p><h3 id="agr-009-—-publicacion-segura-de-configuracion-y-paquetes-de-servicio" tabindex="-1">AGR-009 — Publicación segura de configuración y paquetes de servicio <a class="header-anchor" href="#agr-009-—-publicacion-segura-de-configuracion-y-paquetes-de-servicio" aria-label="Permalink to &quot;AGR-009 — Publicación segura de configuración y paquetes de servicio&quot;">​</a></h3><p><strong>Prioridad:</strong> P0. <strong>Diagnóstico:</strong> Detalle insuficiente. <strong>Base:</strong> secciones 6, 51, 65–66, 72, 81.</p><p><strong>Qué falta concretar y por qué:</strong> La configuración versionada y la copia existen conceptualmente, pero falta definir cómo se publica un conjunto coherente y cómo se evita aplicar solo una parte.</p><p><strong>Propuesta:</strong> Crear una versión de configuración que reúna dependencias, validaciones, simulación, revisión y fecha efectiva. Copiar a borrador y mostrar diferencias. Separar cambios comerciales, fiscales y de presentación; una corrección de label no debe generar una revisión tarifaria innecesaria. No sobrescribir contratos vigentes sin política.</p><p><strong>Ejemplo:</strong> Copiar Internet a B importa formularios, pero la publicación se detiene si no hay equivalencia contable o una tarifa aplicable para B.</p><p><strong>Criterio de aceptación:</strong> La publicación es íntegra y auditable; no queda un plan visible sin precio o con un impuesto del tenant origen por una actualización parcial.</p><h3 id="agr-010-—-historia-con-fecha-efectiva-y-fecha-de-registro" tabindex="-1">AGR-010 — Historia con fecha efectiva y fecha de registro <a class="header-anchor" href="#agr-010-—-historia-con-fecha-efectiva-y-fecha-de-registro" aria-label="Permalink to &quot;AGR-010 — Historia con fecha efectiva y fecha de registro&quot;">​</a></h3><p><strong>Prioridad:</strong> P0. <strong>Diagnóstico:</strong> Detalle insuficiente. <strong>Base:</strong> secciones 4, 6–11, 51, 55, 69, 75, 83.</p><p><strong>Qué falta concretar y por qué:</strong> Existen vigencias, pero falta una regla transversal para cambios retroactivos, datos recibidos tarde y reconstrucción de lo conocido en una fecha.</p><p><strong>Propuesta:</strong> Conservar fecha efectiva del hecho y fecha en que el sistema lo recibió, además de su origen. Definir qué puede corregirse en borrador y qué exige un ajuste de operación emitida/cerrada. Las consultas históricas deben declarar qué fecha interpretan.</p><p><strong>Ejemplo:</strong> Una instalación realizada el 10 se sincroniza el 12; una tarifa cargada el 15 tiene vigencia autorizada desde el 1. No son el mismo tipo de retroactividad.</p><p><strong>Criterio de aceptación:</strong> Se puede explicar una factura con los datos y reglas que utilizó, y reconstruir la corrección posterior sin reescribir silenciosamente el documento original.</p><h3 id="agr-011-—-invariantes-monetarias-y-unica-fuente-del-saldo" tabindex="-1">AGR-011 — Invariantes monetarias y única fuente del saldo <a class="header-anchor" href="#agr-011-—-invariantes-monetarias-y-unica-fuente-del-saldo" aria-label="Permalink to &quot;AGR-011 — Invariantes monetarias y única fuente del saldo&quot;">​</a></h3><p><strong>Prioridad:</strong> P0. <strong>Diagnóstico:</strong> Detalle insuficiente. <strong>Base:</strong> secciones 10–14, 22, 40, 44, 51, 55, 75, 78.</p><p><strong>Qué falta concretar y por qué:</strong> Las conciliaciones y ejemplos están bien planteados, pero falta convertirlos en reglas obligatorias del diseño y la persistencia.</p><p><strong>Propuesta:</strong> Definir representación decimal, precisión por concepto, redondeo, moneda y reglas de compensación. El saldo comercial se deriva de movimientos válidos e imputaciones, no de campos editables independientes. Mantener control de documentos, auxiliar, caja/banco y contabilidad con diferencias explicadas.</p><p><strong>Ejemplo:</strong> Una factura de ARS 13.000 con ARS 5.000 imputados tiene ARS 8.000 de saldo aunque el resumen se regenere o cambie su presentación.</p><p><strong>Criterio de aceptación:</strong> El total no depende de la pantalla o proceso que lo consulte; ningún ajuste de saldo carece de operación, causa, autor y contrapartida.</p><h3 id="agr-012-—-pagos-excedentes-anticipos-y-cobros-sin-identificar" tabindex="-1">AGR-012 — Pagos excedentes, anticipos y cobros sin identificar <a class="header-anchor" href="#agr-012-—-pagos-excedentes-anticipos-y-cobros-sin-identificar" aria-label="Permalink to &quot;AGR-012 — Pagos excedentes, anticipos y cobros sin identificar&quot;">​</a></h3><p><strong>Prioridad:</strong> P1. <strong>Diagnóstico:</strong> No explicitado. <strong>Base:</strong> secciones 11–13, 40, 44, 68, 75.</p><p><strong>Qué falta concretar y por qué:</strong> Se contemplan pagos parciales y a cuenta, pero no está cerrado el tratamiento de excedentes, transferencias no identificadas y pagos de terceros.</p><p><strong>Propuesta:</strong> Crear un circuito de pendientes de identificación y saldo a favor, con conciliación, responsable y aplicación autorizada. Definir qué datos se requieren para identificar al titular beneficiado y cómo se trata un pago anterior a la factura. No aplicar un excedente a otro conviviente o servicio por inferencia.</p><p><strong>Ejemplo:</strong> Ingresan ARS 15.000 para una factura de ARS 13.000: se cancela la obligación y quedan ARS 2.000 a favor o pendientes de aplicación según la política acordada.</p><p><strong>Criterio de aceptación:</strong> Cada peso recibido queda explicado como cancelación, crédito o pendiente; no se pierden excedentes ni se asignan fondos solo por dirección, nombre parecido o imagen de comprobante.</p><h3 id="agr-013-—-devoluciones-y-reversos-con-sus-dos-efectos" tabindex="-1">AGR-013 — Devoluciones y reversos con sus dos efectos <a class="header-anchor" href="#agr-013-—-devoluciones-y-reversos-con-sus-dos-efectos" aria-label="Permalink to &quot;AGR-013 — Devoluciones y reversos con sus dos efectos&quot;">​</a></h3><p><strong>Prioridad:</strong> P1. <strong>Diagnóstico:</strong> Detalle insuficiente. <strong>Base:</strong> secciones 10–14, 21–22, 53, 61, 75.</p><p><strong>Qué falta concretar y por qué:</strong> La base menciona devoluciones y contracargos, pero falta el expediente que distingue corrección comercial, autorización y devolución efectiva de dinero.</p><p><strong>Propuesta:</strong> Definir solicitud, causa, documento correctivo si corresponde, aprobación, cuenta a reintegrar, ejecución financiera y conciliación. Mantener vinculadas las operaciones originales y reversos. Evaluar efectos en promociones, mora, financiación y períodos cerrados.</p><p><strong>Ejemplo:</strong> Emitir un crédito de ARS 2.000 no significa que el banco ya devolvió ARS 2.000. Un contracargo puede reabrir una obligación sin borrar el recibo original.</p><p><strong>Criterio de aceptación:</strong> Se puede explicar por separado el saldo comercial y el reintegro pendiente/ejecutado; no se devuelve dos veces al repetir una orden.</p><h3 id="agr-014-—-vida-completa-de-convenios-y-financiacion" tabindex="-1">AGR-014 — Vida completa de convenios y financiación <a class="header-anchor" href="#agr-014-—-vida-completa-de-convenios-y-financiacion" aria-label="Permalink to &quot;AGR-014 — Vida completa de convenios y financiación&quot;">​</a></h3><p><strong>Prioridad:</strong> P1. <strong>Diagnóstico:</strong> Detalle insuficiente. <strong>Base:</strong> secciones 14, 23, 51, 68, 72.</p><p><strong>Qué falta concretar y por qué:</strong> Existen planes y acuerdos, pero faltan reglas de sustitución de deuda, refinanciación, cancelación anticipada, incumplimiento y conciliación de cuotas.</p><p><strong>Propuesta:</strong> Conservar obligaciones incluidas, capital, intereses y componentes del acuerdo; definir qué sigue exigible y qué queda reemplazado. Separar venta financiada y regularización. Precisar aplicación de pagos, cambios de tasa si fueran válidos y efecto de baja del servicio.</p><p><strong>Ejemplo:</strong> Una deuda incluida en un convenio no puede seguir reclamándose íntegramente junto con todas sus cuotas como si fueran obligaciones adicionales.</p><p><strong>Criterio de aceptación:</strong> Se concilian deuda de origen, pagos, capital pendiente y cargos del acuerdo sin doble exigencia ni cuotas huérfanas.</p><h3 id="agr-015-—-cierre-y-aprobacion-de-cada-ciclo-de-facturacion" tabindex="-1">AGR-015 — Cierre y aprobación de cada ciclo de facturación <a class="header-anchor" href="#agr-015-—-cierre-y-aprobacion-de-cada-ciclo-de-facturacion" aria-label="Permalink to &quot;AGR-015 — Cierre y aprobación de cada ciclo de facturación&quot;">​</a></h3><p><strong>Prioridad:</strong> P0. <strong>Diagnóstico:</strong> Detalle insuficiente. <strong>Base:</strong> secciones 10, 51, 69, 75.</p><p><strong>Qué falta concretar y por qué:</strong> Los lotes ya tienen validación y excepciones. Falta un cierre de ciclo que establezca si la cooperativa puede dar por terminado el período y quién acepta diferencias.</p><p><strong>Propuesta:</strong> Definir universo congelado o versionado, totales esperados, simulación, aprobación y emisión. Clasificar cada seleccionado como emitido, observado, pendiente, excluido con causa o incierto, y cuadrar sus cantidades. Determinar reapertura y reportes de pendientes trasladados.</p><p><strong>Ejemplo:</strong> Un lote de 100 con 98 emitidos y 2 pendientes puede terminar su ejecución, pero el período no debe aparentar 100 facturados.</p><p><strong>Criterio de aceptación:</strong> El cierre produce un acta/reporte de control con responsables y excepciones; no exige ocultar errores para cerrar ni deja casos sin seguimiento.</p><h3 id="agr-016-—-ejecucion-fiable-de-acciones-entre-componentes" tabindex="-1">AGR-016 — Ejecución fiable de acciones entre componentes <a class="header-anchor" href="#agr-016-—-ejecucion-fiable-de-acciones-entre-componentes" aria-label="Permalink to &quot;AGR-016 — Ejecución fiable de acciones entre componentes&quot;">​</a></h3><p><strong>Prioridad:</strong> P0. <strong>Diagnóstico:</strong> Detalle insuficiente. <strong>Base:</strong> secciones 13, 47, 54, 58–59, 61, 69, 73.</p><p><strong>Qué falta concretar y por qué:</strong> Se pide evitar duplicados, pero falta una política común de identidad de operación, entrega de mensajes y reparación de acciones incompletas.</p><p><strong>Propuesta:</strong> Definir identificador de operación por tenant, reintento seguro, estados intermedios, correlación y resultado final. Registrar de forma durable el cambio y el trabajo pendiente para otros componentes; reintentar sin volver a aplicar lo ya confirmado. No exigir una tecnología específica ni presumir entrega única de mensajes.</p><p><strong>Ejemplo:</strong> El servicio quedó instalado y se registró stock, pero falló crear el cargo: se repara el paso faltante y no se instala ni descuenta otra vez.</p><p><strong>Criterio de aceptación:</strong> Un fallo después de confirmar un pago o activar un servicio puede recuperarse sin duplicar efectos; existe una bandeja técnica/operativa para casos no reparables automáticamente.</p><h3 id="agr-017-—-calendarios-prorrateos-y-cambios-dentro-del-periodo" tabindex="-1">AGR-017 — Calendarios, prorrateos y cambios dentro del período <a class="header-anchor" href="#agr-017-—-calendarios-prorrateos-y-cambios-dentro-del-periodo" aria-label="Permalink to &quot;AGR-017 — Calendarios, prorrateos y cambios dentro del período&quot;">​</a></h3><p><strong>Prioridad:</strong> P1. <strong>Diagnóstico:</strong> Detalle insuficiente. <strong>Base:</strong> secciones 6, 51, 69, 72–73.</p><p><strong>Qué falta concretar y por qué:</strong> Hay ejemplos de prorrateo y fechas, pero falta una especificación de fronteras que sirva para todos los motores de cálculo.</p><p><strong>Propuesta:</strong> Definir zona horaria, inclusión de días, meses cortos, feriados, cambio de plan o titular, suspensión, promoción y redondeo por tramo. Diferenciar calendario de lectura, liquidación, emisión y vencimiento. Guardar cada tramo y su regla.</p><p><strong>Ejemplo:</strong> Una promoción de tres ciclos puede consumir o no un primer ciclo parcial; cualquiera sea la decisión, debe estar definida y explicarse al socio.</p><p><strong>Criterio de aceptación:</strong> Los casos de fin de mes, año bisiesto, cambios a mitad de período y carga tardía producen resultados aprobados y reproducibles, no dependientes del horario del servidor.</p><h3 id="agr-018-—-migracion-y-cambio-operativo-desde-el-sistema-anterior" tabindex="-1">AGR-018 — Migración y cambio operativo desde el sistema anterior <a class="header-anchor" href="#agr-018-—-migracion-y-cambio-operativo-desde-el-sistema-anterior" aria-label="Permalink to &quot;AGR-018 — Migración y cambio operativo desde el sistema anterior&quot;">​</a></h3><p><strong>Prioridad:</strong> P1. <strong>Diagnóstico:</strong> Detalle insuficiente. <strong>Base:</strong> secciones 31, 35, 64, 95.</p><p><strong>Qué falta concretar y por qué:</strong> La migración está contemplada, pero falta una estrategia ejecutable para la primera cooperativa y su continuidad diaria.</p><p><strong>Propuesta:</strong> Planificar inventario de fuentes, correspondencias, limpieza, ensayo completo, conciliación por servicio y titular, congelamiento de cambios, carga final, aceptación y plan de retorno. Definir qué historia se importa y qué queda disponible solo para consulta. No usar una misma persona/domicilio para fusionar contratos distintos.</p><p><strong>Ejemplo:</strong> Un saldo inicial de ARS 8.000 debe conservar titular, contrato, documento/período y origen, además de coincidir con el total contable.</p><p><strong>Criterio de aceptación:</strong> Antes de habilitar producción se cuadran socios, contratos activos, equipos, deuda y fondos; los cambios realizados después del corte no desaparecen si se debe volver al sistema anterior.</p><h3 id="agr-019-—-recuperacion-y-restauracion-por-tenant" tabindex="-1">AGR-019 — Recuperación y restauración por tenant <a class="header-anchor" href="#agr-019-—-recuperacion-y-restauracion-por-tenant" aria-label="Permalink to &quot;AGR-019 — Recuperación y restauración por tenant&quot;">​</a></h3><p><strong>Prioridad:</strong> P0. <strong>Diagnóstico:</strong> Detalle insuficiente. <strong>Base:</strong> secciones 29, 54, 60, 64.</p><p><strong>Qué falta concretar y por qué:</strong> Ya se prevén copias y pruebas. Falta precisar pérdida admisible de datos, tiempo de recuperación y cómo restaurar una cooperativa sin retroceder las demás.</p><p><strong>Propuesta:</strong> Acordar RPO —datos que se tolera perder— y RTO —tiempo objetivo de recuperación— por proceso, sin inventar cifras. Diseñar restauración selectiva, claves, adjuntos, auditoría y conciliación con terceros. Una restauración no puede deshacer una emisión fiscal o un cobro externo ya confirmado.</p><p><strong>Ejemplo:</strong> Restaurar una copia anterior al último pago exige recuperar/conciliar ese pago desde evidencia verificable, sin volver a cobrarlo.</p><p><strong>Criterio de aceptación:</strong> Un ensayo demuestra recuperación del tenant, integridad de documentos y conciliación externa; no basta comprobar que existe un archivo de backup.</p><h3 id="agr-020-—-capacidad-rendimiento-y-aislamiento-de-carga" tabindex="-1">AGR-020 — Capacidad, rendimiento y aislamiento de carga <a class="header-anchor" href="#agr-020-—-capacidad-rendimiento-y-aislamiento-de-carga" aria-label="Permalink to &quot;AGR-020 — Capacidad, rendimiento y aislamiento de carga&quot;">​</a></h3><p><strong>Prioridad:</strong> P0. <strong>Diagnóstico:</strong> Pendiente ya identificado. <strong>Base:</strong> secciones 54, 58–60, 64, 69.</p><p><strong>Qué falta concretar y por qué:</strong> No hay un perfil cuantificado de volumen y simultaneidad que permita elegir infraestructura y probar el servicio.</p><p><strong>Propuesta:</strong> Relevar tenants, usuarios, contratos, documentos por ciclo, tamaño de archivos, mensajes, consultas BI y trabajos de fondo. Definir objetivos de respuesta y ventanas batch, límites por tenant y prioridades. Proponer separar trabajos pesados del uso interactivo según las mediciones.</p><p><strong>Ejemplo:</strong> Un tenant exporta toda su historia mientras otro cobra en caja; la exportación no debe monopolizar recursos y bloquear la cobranza.</p><p><strong>Criterio de aceptación:</strong> Se validan escenarios de carga representativos con métricas por tenant; las cifras acordadas son verificables y no se promete capacidad ilimitada.</p><h3 id="agr-021-—-operacion-de-apis-y-conectores-ademas-de-su-desarrollo" tabindex="-1">AGR-021 — Operación de APIs y conectores, además de su desarrollo <a class="header-anchor" href="#agr-021-—-operacion-de-apis-y-conectores-ademas-de-su-desarrollo" aria-label="Permalink to &quot;AGR-021 — Operación de APIs y conectores, además de su desarrollo&quot;">​</a></h3><p><strong>Prioridad:</strong> P1. <strong>Diagnóstico:</strong> Detalle insuficiente. <strong>Base:</strong> secciones 13, 31, 59, 61, 79.</p><p><strong>Qué falta concretar y por qué:</strong> Las APIs y mecanismos externos están definidos, pero falta un contrato operativo uniforme para fallos, cambios de esquema y vencimiento de credenciales.</p><p><strong>Propuesta:</strong> Estandarizar códigos de error, correlación, límites, versiones, reintentos, revocación y manejo de indisponibilidad. Definir cola/bandeja de operaciones detenidas y reconciliación. Evaluar notificaciones a sistemas terceros solo si el caso lo necesita, sin hacer obligatorio un webhook para toda integración.</p><p><strong>Ejemplo:</strong> Un certificado fiscal vence o cambia el formato del archivo: se identifica la integración afectada sin marcar como erróneos todos los socios.</p><p><strong>Criterio de aceptación:</strong> Existe estado observable por conector y tenant, causa accionable y mecanismo de recuperación; los errores públicos no revelan secretos ni detalles internos. Puede evaluarse RFC 9457 como formato [R3].</p><h3 id="agr-022-—-contrato-semantico-para-dashboards-y-bi" tabindex="-1">AGR-022 — Contrato semántico para dashboards y BI <a class="header-anchor" href="#agr-022-—-contrato-semantico-para-dashboards-y-bi" aria-label="Permalink to &quot;AGR-022 — Contrato semántico para dashboards y BI&quot;">​</a></h3><p><strong>Prioridad:</strong> P1. <strong>Diagnóstico:</strong> Detalle insuficiente. <strong>Base:</strong> secciones 30, 54–55, 59, 75.</p><p><strong>Qué falta concretar y por qué:</strong> La exposición de datos está cubierta, pero no todas las métricas tienen una definición única de fecha, universo y granularidad.</p><p><strong>Propuesta:</strong> Crear un catálogo de indicadores con fórmula, nivel —persona, contrato, factura, pago—, fecha de corte, estado incluido y actualización. Definir exportaciones consistentes y separación real/simulado. Explicar qué significa Facturado, Cobrado, Acreditado y Saldo.</p><p><strong>Ejemplo:</strong> Sumar un resumen de cuenta y sus facturas duplica la deuda; sumar filas por concepto puede duplicar el total de una factura.</p><p><strong>Criterio de aceptación:</strong> El dashboard interno y BI reconcilian para el mismo universo y corte; un conjunto de datos indica granularidad y no mezcla simulaciones sin identificarlas.</p><h3 id="agr-023-—-expediente-documental-y-conservacion-de-evidencia" tabindex="-1">AGR-023 — Expediente documental y conservación de evidencia <a class="header-anchor" href="#agr-023-—-expediente-documental-y-conservacion-de-evidencia" aria-label="Permalink to &quot;AGR-023 — Expediente documental y conservación de evidencia&quot;">​</a></h3><p><strong>Prioridad:</strong> P1. <strong>Diagnóstico:</strong> Detalle insuficiente. <strong>Base:</strong> secciones 3, 17, 43, 47, 54, 61, 73, 90–91.</p><p><strong>Qué falta concretar y por qué:</strong> Hay documentos, fotos y firma, pero falta un ciclo transversal de expediente, versión, sustitución, retención y descarga autorizada.</p><p><strong>Propuesta:</strong> Clasificar documentos por finalidad y sensibilidad, relacionarlos con su operación, conservar versión aceptada y determinar quién puede verlos o sustituirlos. Definir retención y archivo según el marco que se releve, sin inventar plazos universales. Proteger descargas fuera de sesión y referencias compartidas.</p><p><strong>Ejemplo:</strong> La foto de una instalación o la firma no debe seguir accesible mediante un enlace antiguo después de revocar una autorización.</p><p><strong>Criterio de aceptación:</strong> Se identifica qué versión de documento respalda una acción y quién la consultó cuando ese acceso sea auditable; no se sustituyen evidencias históricas silenciosamente.</p><h3 id="agr-024-—-comunicaciones-entrega-y-constancias" tabindex="-1">AGR-024 — Comunicaciones, entrega y constancias <a class="header-anchor" href="#agr-024-—-comunicaciones-entrega-y-constancias" aria-label="Permalink to &quot;AGR-024 — Comunicaciones, entrega y constancias&quot;">​</a></h3><p><strong>Prioridad:</strong> P1. <strong>Diagnóstico:</strong> Detalle insuficiente. <strong>Base:</strong> secciones 26, 43, 47, 50, 52–54, 73.</p><p><strong>Qué falta concretar y por qué:</strong> Se registra el resultado de mensajes, pero falta concretar cuándo una comunicación satisface un hito del proceso y qué hacer si falla.</p><p><strong>Propuesta:</strong> Diferenciar creado, encolado, aceptado por proveedor, entregado y evidencia requerida. Definir destinatario verificado, versión de plantilla, reintento, alternativa de canal y revisión. Separar avisos comerciales, operativos y constancias reguladas; no declarar equivalencia legal de cualquier email.</p><p><strong>Ejemplo:</strong> Una intimación o constancia de baja no se considera cumplida solo porque el proveedor de correo aceptó una solicitud.</p><p><strong>Criterio de aceptación:</strong> El caso conserva contenido, destinatario, fechas y evidencia; un fallo de entrega produce acción y no queda oculto tras Mensaje enviado.</p><h3 id="agr-025-—-visitas-y-operacion-sin-conexion-con-conflictos" tabindex="-1">AGR-025 — Visitas y operación sin conexión con conflictos <a class="header-anchor" href="#agr-025-—-visitas-y-operacion-sin-conexion-con-conflictos" aria-label="Permalink to &quot;AGR-025 — Visitas y operación sin conexión con conflictos&quot;">​</a></h3><p><strong>Prioridad:</strong> P1. <strong>Diagnóstico:</strong> Detalle insuficiente. <strong>Base:</strong> secciones 8, 17, 50, 73, 77.</p><p><strong>Qué falta concretar y por qué:</strong> El trabajo offline y las reservas están mencionados, pero falta resolver reservas simultáneas y cambios del servidor mientras el técnico está desconectado.</p><p><strong>Propuesta:</strong> Definir reserva temporal y confirmada, capacidad del recurso, expiración, reprogramación y asignación. Versionar la tarea descargada y tratar conflictos al sincronizar. Registrar fecha real de intervención y fecha de recepción; no sobrescribir equipos o titulares ya modificados sin revisión.</p><p><strong>Ejemplo:</strong> Un técnico instala un equipo offline mientras la orden fue cancelada en administración: se recibe la evidencia y se revisa el conflicto, en vez de borrar lo realizado o activar sin control.</p><p><strong>Criterio de aceptación:</strong> No hay doble asignación del mismo equipo/turno por carrera; el conflicto conserva ambas evidencias y tiene un responsable de resolución.</p><h3 id="agr-026-—-valorizacion-activos-y-reparacion-de-equipos" tabindex="-1">AGR-026 — Valorización, activos y reparación de equipos <a class="header-anchor" href="#agr-026-—-valorizacion-activos-y-reparacion-de-equipos" aria-label="Permalink to &quot;AGR-026 — Valorización, activos y reparación de equipos&quot;">​</a></h3><p><strong>Prioridad:</strong> P1. <strong>Diagnóstico:</strong> Pendiente ya identificado. <strong>Base:</strong> secciones 7, 18, 20, 55, 73, 75, 78.</p><p><strong>Qué falta concretar y por qué:</strong> La custodia física está bien desarrollada. Sigue pendiente la relación entre cantidad, costo, activo propio, bien vendido, depreciación y reparación.</p><p><strong>Propuesta:</strong> Definir categorías de material/activo, método de valoración aprobado, costos de ingreso y series/lotes. Gestionar reparación, garantía, reemplazo, baja técnica y disposición. Si hay activo fijo, acordar amortización y su relación contable; no activar ese alcance por inferencia para todo artículo.</p><p><strong>Ejemplo:</strong> Un módem propio en casa del socio no desaparece del patrimonio por salir del depósito; si se vende, su tratamiento comercial/contable es diferente.</p><p><strong>Criterio de aceptación:</strong> Existencias, custodia y valoración pueden conciliarse; el traslado físico no duplica un gasto ni una venta y una sustitución conserva historia.</p><h3 id="agr-027-—-control-de-compra-recepcion-y-factura-de-proveedor" tabindex="-1">AGR-027 — Control de compra, recepción y factura de proveedor <a class="header-anchor" href="#agr-027-—-control-de-compra-recepcion-y-factura-de-proveedor" aria-label="Permalink to &quot;AGR-027 — Control de compra, recepción y factura de proveedor&quot;">​</a></h3><p><strong>Prioridad:</strong> P1. <strong>Diagnóstico:</strong> Detalle insuficiente. <strong>Base:</strong> secciones 19–21, 61, 75, 78.</p><p><strong>Qué falta concretar y por qué:</strong> La vinculación compra-recepción-factura existe, pero faltan tolerancias, excepciones y autorización de diferencias.</p><p><strong>Propuesta:</strong> Comparar cantidades y condiciones de orden, recepción y factura; definir entregas parciales, excesos, devolución, factura anticipada y servicios sin recepción material. Separar quién compra, recibe y aprueba pago y registrar el tratamiento de compras sin orden previa.</p><p><strong>Ejemplo:</strong> Se pidieron diez medidores, llegaron seis y se facturaron diez: el sistema no paga automáticamente como si se hubieran recibido todos.</p><p><strong>Criterio de aceptación:</strong> Cada diferencia está aprobada o pendiente con causa; el pago respeta lo autorizado y los movimientos de stock representan lo físicamente recibido.</p><h3 id="agr-028-—-presupuestos-y-compromisos-de-fondos" tabindex="-1">AGR-028 — Presupuestos y compromisos de fondos <a class="header-anchor" href="#agr-028-—-presupuestos-y-compromisos-de-fondos" aria-label="Permalink to &quot;AGR-028 — Presupuestos y compromisos de fondos&quot;">​</a></h3><p><strong>Prioridad:</strong> P2. <strong>Diagnóstico:</strong> Pendiente ya identificado. <strong>Base:</strong> secciones 19, 21–22, 55, 75.</p><p><strong>Qué falta concretar y por qué:</strong> Hay proyección y se menciona presupuesto como extensión, pero no se distingue todavía crédito presupuestario, compromiso, obligación y pago.</p><p><strong>Propuesta:</strong> Si el alcance ERP lo requiere, definir presupuestos por servicio/centro, versiones, compromisos de compra y comparación con devengado/pagado. Establecer límites de autorización, excepciones y liberación de compromisos al cancelar. Mantener este alcance como decisión explícita.</p><p><strong>Ejemplo:</strong> Una compra aprobada compromete fondos aunque todavía no exista factura; al cancelarla se libera ese compromiso sin inventar un ingreso.</p><p><strong>Criterio de aceptación:</strong> Los informes distinguen presupuesto, comprometido, devengado y pagado y no suman esos estados como gastos independientes.</p><h3 id="agr-029-—-capital-y-relacion-institucional-del-asociado" tabindex="-1">AGR-029 — Capital y relación institucional del asociado <a class="header-anchor" href="#agr-029-—-capital-y-relacion-institucional-del-asociado" aria-label="Permalink to &quot;AGR-029 — Capital y relación institucional del asociado&quot;">​</a></h3><p><strong>Prioridad:</strong> P1. <strong>Diagnóstico:</strong> Pendiente ya identificado. <strong>Base:</strong> secciones 3, 27, 75, 83.</p><p><strong>Qué falta concretar y por qué:</strong> El módulo institucional menciona aportes, pero el detalle está muy por debajo del de servicios. Puede ser relevante para una cooperativa real.</p><p><strong>Propuesta:</strong> Relevar suscripción/integración de capital, cuotas/aportes, estado institucional, documentación, egreso y eventual devolución según estatuto y marco aplicable. Mantener auxiliar institucional distinto de la deuda por servicios; no inventar obligaciones universales para todas las cooperativas.</p><p><strong>Ejemplo:</strong> Dar de baja Internet no produce automáticamente egreso como asociado ni devolución de capital; cobrar un aporte no lo convierte en ingreso por consumo.</p><p><strong>Criterio de aceptación:</strong> La cooperativa puede explicar relación institucional, capital y servicios por separado; las reglas económicas concretas tienen respaldo y validación contable.</p><h3 id="agr-030-—-gobierno-de-la-ia-y-verificacion-de-sus-resultados" tabindex="-1">AGR-030 — Gobierno de la IA y verificación de sus resultados <a class="header-anchor" href="#agr-030-—-gobierno-de-la-ia-y-verificacion-de-sus-resultados" aria-label="Permalink to &quot;AGR-030 — Gobierno de la IA y verificación de sus resultados&quot;">​</a></h3><p><strong>Prioridad:</strong> P0. <strong>Diagnóstico:</strong> Detalle insuficiente. <strong>Base:</strong> secciones 47, 54, 60, 65, 73, 91.</p><p><strong>Qué falta concretar y por qué:</strong> La IA tiene límites bien señalados, pero faltan responsables, versiones, evaluación, evidencia y comportamiento ante falta de disponibilidad.</p><p><strong>Propuesta:</strong> Registrar función permitida, fuente, ámbito de tenant, versión y resultado. Definir cuándo confirma una persona, cómo se corrige y cómo se atiende sin IA. Tratar mensajes y adjuntos como datos que no pueden cambiar permisos ni instrucciones del sistema. Evaluar errores por servicio y derivar casos sensibles.</p><p><strong>Ejemplo:</strong> Una foto o mensaje que pida ignorar instrucciones no habilita al bot a consultar otro tenant; una clasificación incierta deja el caso para supervisión.</p><p><strong>Criterio de aceptación:</strong> Se puede reconstruir qué sugirió la IA y qué decidió el operador; un fallo o respuesta insegura no bloquea la recepción del reclamo ni ejecuta cobros o decisiones clínicas.</p><h3 id="agr-031-—-moderacion-y-ciclo-de-vida-de-la-comunidad" tabindex="-1">AGR-031 — Moderación y ciclo de vida de la comunidad <a class="header-anchor" href="#agr-031-—-moderacion-y-ciclo-de-vida-de-la-comunidad" aria-label="Permalink to &quot;AGR-031 — Moderación y ciclo de vida de la comunidad&quot;">​</a></h3><p><strong>Prioridad:</strong> P2. <strong>Diagnóstico:</strong> No explicitado. <strong>Base:</strong> secciones 26, 46, 65, 82.</p><p><strong>Qué falta concretar y por qué:</strong> La publicación de noticias existe, pero falta definir participación, moderación y tratamiento de contenido denunciado si se habilitan comentarios o aportes.</p><p><strong>Propuesta:</strong> Precisar si el muro es solo editorial o también participativo. Si hay participación, definir quién publica, audiencias, denuncia, ocultamiento, revisión, conservación y respuesta. Distinguir borrar contenido visible de eliminar evidencia; revisar datos personales en fotos y mensajes.</p><p><strong>Ejemplo:</strong> Una publicación dirigida a empleados no se vuelve pública al copiar una plantilla o cambiar el perfil del autor.</p><p><strong>Criterio de aceptación:</strong> No se habilitan comentarios solo por reutilizar Connectyx; las interacciones permitidas y la moderación tienen alcance y responsables definidos.</p><h3 id="agr-032-—-accesibilidad-y-autogestion-tolerante-a-errores" tabindex="-1">AGR-032 — Accesibilidad y autogestión tolerante a errores <a class="header-anchor" href="#agr-032-—-accesibilidad-y-autogestion-tolerante-a-errores" aria-label="Permalink to &quot;AGR-032 — Accesibilidad y autogestión tolerante a errores&quot;">​</a></h3><p><strong>Prioridad:</strong> P1. <strong>Diagnóstico:</strong> Detalle insuficiente. <strong>Base:</strong> secciones 25, 43, 50, 60, 65, 67, 73.</p><p><strong>Qué falta concretar y por qué:</strong> La personalización visual y de términos no incluye todavía un objetivo verificable de accesibilidad y resolución de formularios incompletos.</p><p><strong>Propuesta:</strong> Proponer WCAG 2.2 nivel AA como objetivo a validar [R1], junto con recorridos simples, teclado, foco, contraste, etiquetas, mensajes claros y alternativas al mapa. Guardar borradores y recuperar carga interrumpida. Validar que los colores del tenant y textos largos no rompan accesibilidad.</p><p><strong>Ejemplo:</strong> Una persona puede solicitar un servicio o pagar sin operar un mapa; un error conserva los datos y señala qué falta sin perder todo el trámite.</p><p><strong>Criterio de aceptación:</strong> Los recorridos esenciales se prueban con teclado y ayudas de acceso; existe alternativa al gesto táctil o componente inaccesible y no se afirma conformidad sin verificación.</p><h3 id="agr-033-—-ciclo-de-privacidad-conservacion-y-salida-de-datos" tabindex="-1">AGR-033 — Ciclo de privacidad, conservación y salida de datos <a class="header-anchor" href="#agr-033-—-ciclo-de-privacidad-conservacion-y-salida-de-datos" aria-label="Permalink to &quot;AGR-033 — Ciclo de privacidad, conservación y salida de datos&quot;">​</a></h3><p><strong>Prioridad:</strong> P0. <strong>Diagnóstico:</strong> Detalle insuficiente. <strong>Base:</strong> secciones 29, 54, 59–60, 64, 77, 83, 90–91.</p><p><strong>Qué falta concretar y por qué:</strong> Se protege el acceso, pero falta un ciclo transversal de finalidad, conservación, solicitudes de personas y salida de la cooperativa.</p><p><strong>Propuesta:</strong> Inventariar categorías de datos, finalidad, responsables, acceso y plazo a validar. Diferenciar corrección de identidad, baja de usuario, archivo contractual y eliminación cuando proceda. Definir exportación de salida y tratamiento de copias/adjuntos; consultar el marco aplicable antes de fijar plazos o excepciones.</p><p><strong>Ejemplo:</strong> Eliminar una cuenta de acceso no puede destruir una factura válida ni el registro de una inhumación; tampoco justifica conservar indefinidamente todo comentario sin criterio.</p><p><strong>Criterio de aceptación:</strong> Existe una decisión documentada por categoría y un procedimiento de atención; las APIs de BI no exponen por defecto información sanitaria o documentos innecesarios.</p><h3 id="agr-034-—-soporte-con-acceso-temporal-y-responsabilidad" tabindex="-1">AGR-034 — Soporte con acceso temporal y responsabilidad <a class="header-anchor" href="#agr-034-—-soporte-con-acceso-temporal-y-responsabilidad" aria-label="Permalink to &quot;AGR-034 — Soporte con acceso temporal y responsabilidad&quot;">​</a></h3><p><strong>Prioridad:</strong> P1. <strong>Diagnóstico:</strong> Detalle insuficiente. <strong>Base:</strong> secciones 42, 54, 60, 64.</p><p><strong>Qué falta concretar y por qué:</strong> El soporte es un diferencial esperado, pero falta definir cómo interviene en datos de una cooperativa y cómo se controla esa capacidad.</p><p><strong>Propuesta:</strong> Establecer solicitud, alcance mínimo, justificación, autorización cuando corresponda, vencimiento, registro y revocación. Diferenciar observar de operar; cualquier acción debe conservar identidad del agente de soporte y del tenant. No resolver mediante compartir contraseñas o impersonación sin rastro.</p><p><strong>Ejemplo:</strong> Para corregir una configuración se habilita una intervención acotada al caso; no se concede a todo soporte acceso permanente a todas las cooperativas.</p><p><strong>Criterio de aceptación:</strong> Cada intervención sensible tiene expediente, alcance y evidencia; vencida la autorización, el agente deja de acceder y el tenant puede consultar las actuaciones permitidas.</p><h3 id="agr-035-—-entornos-pruebas-y-evidencias-antes-de-cada-entrega" tabindex="-1">AGR-035 — Entornos, pruebas y evidencias antes de cada entrega <a class="header-anchor" href="#agr-035-—-entornos-pruebas-y-evidencias-antes-de-cada-entrega" aria-label="Permalink to &quot;AGR-035 — Entornos, pruebas y evidencias antes de cada entrega&quot;">​</a></h3><p><strong>Prioridad:</strong> P0. <strong>Diagnóstico:</strong> Detalle insuficiente. <strong>Base:</strong> secciones 34, 39–40, 54–55, 60, 69, 73.</p><p><strong>Qué falta concretar y por qué:</strong> Existen escenarios de prueba, pero no una política de entornos ni una matriz de verificación contra requisitos, versiones y riesgos.</p><p><strong>Propuesta:</strong> Separar desarrollo, prueba y producción; identificar datos ficticios y bloquear emisiones/cobros reales desde pruebas. Crear un juego canónico de datos para dos tenants, titulares con domicilio compartido y casos de excepción. Vincular pruebas con requisitos, integraciones y versión liberada.</p><p><strong>Ejemplo:</strong> Una simulación fiscal no utiliza credenciales productivas; actualizar la app no puede sustituir el precio de un contrato por un valor del ejemplo documental.</p><p><strong>Criterio de aceptación:</strong> Cada entrega del piloto tiene evidencia de recorridos críticos, permisos negativos, conciliación e interrupción/reintento; un fallo relevante impide promover la versión hasta resolverlo.</p><h3 id="agr-036-—-plan-de-entrega-y-aceptacion-de-la-cooperativa-piloto" tabindex="-1">AGR-036 — Plan de entrega y aceptación de la cooperativa piloto <a class="header-anchor" href="#agr-036-—-plan-de-entrega-y-aceptacion-de-la-cooperativa-piloto" aria-label="Permalink to &quot;AGR-036 — Plan de entrega y aceptación de la cooperativa piloto&quot;">​</a></h3><p><strong>Prioridad:</strong> P0. <strong>Diagnóstico:</strong> Pendiente ya identificado. <strong>Base:</strong> secciones 35, 37, 58, 64, 95.</p><p><strong>Qué falta concretar y por qué:</strong> La visión abarca seis dominios y un ERP/CRM completos, pero falta convertirla en entregas aceptables sin intentar desarrollar todo simultáneamente.</p><p><strong>Propuesta:</strong> Definir el alcance final y un piloto de una prestación concreta con una cooperativa real, sin retirar el resto del catálogo objetivo. Incluir plataforma básica, dos tenants de prueba para aislamiento y el recorrido completo elegido. Acordar responsables, documentación, capacitación, soporte de arranque y aceptación por rol.</p><p><strong>Ejemplo:</strong> Un piloto de Internet debe completar contratación, visita, equipo, factura, pago y reclamo; un conjunto de pantallas sin ese ciclo no equivale a un servicio operativo.</p><p><strong>Criterio de aceptación:</strong> Hay una matriz de capacidades incluidas/excluidas por entrega y criterios de aceptación firmables; ninguna fecha o presupuesto se estima como compromiso sin dimensionar el alcance.</p><h2 id="_5-decisiones-de-diseno-que-recomiendo-adoptar-como-hipotesis-iniciales" tabindex="-1">5. Decisiones de diseño que recomiendo adoptar como hipótesis iniciales <a class="header-anchor" href="#_5-decisiones-de-diseno-que-recomiendo-adoptar-como-hipotesis-iniciales" aria-label="Permalink to &quot;5. Decisiones de diseño que recomiendo adoptar como hipótesis iniciales&quot;">​</a></h2><p>Estas elecciones son propuestas razonadas para contrastar en arquitectura, no decisiones ya tomadas ni instrucciones para implementar un stack particular.</p><h3 id="_5-1-disenar-modulos-con-responsabilidades-claras-antes-de-distribuirlos" tabindex="-1">5.1. Diseñar módulos con responsabilidades claras antes de distribuirlos <a class="header-anchor" href="#_5-1-disenar-modulos-con-responsabilidades-claras-antes-de-distribuirlos" aria-label="Permalink to &quot;5.1. Diseñar módulos con responsabilidades claras antes de distribuirlos&quot;">​</a></h3><p>Usaría como punto de partida un diseño modular con interfaces explícitas y procesos de fondo, y compararía su implementación como aplicación modular o componentes separados según volumen, equipo, reutilización de Connectyx y operación. La existencia de ERP, CRM y comunidad no obliga por sí sola a desplegar muchos microservicios.</p><p>Una separación temprana que sí considero necesaria es la de responsabilidades: contratación decide sobre contratos; operación confirma actuaciones técnicas; facturación emite documentos; cuenta corriente aplica movimientos; pagos confirma transacciones; contabilidad registra su efecto; CRM coordina expedientes. Separación lógica no significa necesariamente bases o servidores diferentes.</p><h3 id="_5-2-identidad-de-acceso-y-relacion-de-negocio-separadas" tabindex="-1">5.2. Identidad de acceso y relación de negocio separadas <a class="header-anchor" href="#_5-2-identidad-de-acceso-y-relacion-de-negocio-separadas" aria-label="Permalink to &quot;5.2. Identidad de acceso y relación de negocio separadas&quot;">​</a></h3><p>Evaluaría identidad de acceso común con pertenencias a tenants y perfiles/roles recalculados al seleccionar ámbito. Los registros de personas/asociados de cada cooperativa permanecen privados y no se fusionan por correo o DNI sin una acción autorizada. Esta hipótesis facilita el caso de persona empleada en una cooperativa y socia de otra, sin otorgar acceso cruzado.</p><h3 id="_5-3-un-auxiliar-comercial-trazable-y-resumenes-derivados" tabindex="-1">5.3. Un auxiliar comercial trazable y resúmenes derivados <a class="header-anchor" href="#_5-3-un-auxiliar-comercial-trazable-y-resumenes-derivados" aria-label="Permalink to &quot;5.3. Un auxiliar comercial trazable y resúmenes derivados&quot;">​</a></h3><p>Mantendría movimientos e imputaciones como fuente del saldo comercial, con integridad definida. Las cuentas por servicio, la vista unificada y el resumen se generan desde esos registros. No guardaría totales editables independientes en cada pantalla que luego deban mantenerse iguales mediante parches.</p><p>Los planes contables y escenarios alternativos consumen operaciones identificadas y mantienen su ámbito. No es necesario adoptar una arquitectura completa de event sourcing para lograr esta trazabilidad: debe elegirse el mecanismo más sencillo que conserve integridad, historia y corrección.</p><h3 id="_5-4-configuracion-por-versiones-publicadas-no-campos-sueltos" tabindex="-1">5.4. Configuración por versiones publicadas, no campos sueltos <a class="header-anchor" href="#_5-4-configuracion-por-versiones-publicadas-no-campos-sueltos" aria-label="Permalink to &quot;5.4. Configuración por versiones publicadas, no campos sueltos&quot;">​</a></h3><p>Productos, conceptos, reglas, formularios y calendarios deben poder revisarse juntos cuando sus dependencias lo requieran. Copiar configuración entre tenants crea un borrador con correspondencias y validaciones; no un enlace vivo a las condiciones comerciales de la cooperativa origen. Los cambios menores de texto pueden tener un circuito más simple que los tarifarios.</p><h3 id="_5-5-automatizacion-con-estados-observables" tabindex="-1">5.5. Automatización con estados observables <a class="header-anchor" href="#_5-5-automatizacion-con-estados-observables" aria-label="Permalink to &quot;5.5. Automatización con estados observables&quot;">​</a></h3><p>Mantendría explícitos Pendiente, Confirmado, Fallido y Resultado incierto para integraciones y actuaciones relevantes, con variantes según dominio. Una cola técnica no debería ser la única explicación de por qué un asociado sigue sin servicio o una factura parece impaga.</p><h3 id="_5-6-autogestion-con-una-tarea-principal-clara-por-pantalla" tabindex="-1">5.6. Autogestión con una tarea principal clara por pantalla <a class="header-anchor" href="#_5-6-autogestion-con-una-tarea-principal-clara-por-pantalla" aria-label="Permalink to &quot;5.6. Autogestión con una tarea principal clara por pantalla&quot;">​</a></h3><p>El socio necesita entender qué tiene contratado, cuánto debe, qué está en trámite y qué puede hacer. Priorizaría Mis servicios, Mis facturas y pagos, Mis gestiones y Noticias; los nombres concretos se resuelven mediante el diccionario del tenant. Mostraría estados del trámite y del servicio por separado, y conservaría la alternativa pública de baja cuando corresponda al flujo ya definido.</p><p>El empleado necesita una bandeja con siguiente acción, responsable y contexto, no solo una lista de casos con estados. El supervisor necesita pendientes sin asignar y excepciones; el administrador, configuración y control. La jerarquía de navegación debe responder a esas tareas y luego aplicar el perfil de pantallas.</p><h2 id="_6-cinco-escenarios-que-conviene-usar-para-verificar-el-diseno" tabindex="-1">6. Cinco escenarios que conviene usar para verificar el diseño <a class="header-anchor" href="#_6-cinco-escenarios-que-conviene-usar-para-verificar-el-diseno" aria-label="Permalink to &quot;6. Cinco escenarios que conviene usar para verificar el diseño&quot;">​</a></h2><h3 id="esc-01-—-pago-excedente-de-un-hermano" tabindex="-1">ESC-01 — Pago excedente de un hermano <a class="header-anchor" href="#esc-01-—-pago-excedente-de-un-hermano" aria-label="Permalink to &quot;ESC-01 — Pago excedente de un hermano&quot;">​</a></h3><p>Dos hermanos tienen Internet en el mismo domicilio. A debe ARS 13.000 y paga ARS 15.000; B tiene deuda propia. Se confirman ARS 13.000 contra A y quedan ARS 2.000 a favor o pendientes de aplicación según la política aprobada. No se paga la deuda de B automáticamente. Cada movimiento se concilia con fondos e imputación. <strong>Propuestas relacionadas:</strong> AGR-006, 007, 011 y 012.</p><h3 id="esc-02-—-correccion-recibida-despues-de-emitir" tabindex="-1">ESC-02 — Corrección recibida después de emitir <a class="header-anchor" href="#esc-02-—-correccion-recibida-despues-de-emitir" aria-label="Permalink to &quot;ESC-02 — Corrección recibida después de emitir&quot;">​</a></h3><p>Se emitió una obligación por ARS 12.000 y después llega evidencia que requiere recalcularla en ARS 15.000. El sistema simula la diferencia de ARS 3.000, solicita el circuito de aprobación y documentación aplicable y conserva el original. No edita su total histórico ni crea otra obligación completa de ARS 15.000 sin resolver la primera. <strong>Relacionadas:</strong> AGR-009, 010, 011, 013 y 015.</p><h3 id="esc-03-—-instalacion-offline-en-conflicto" tabindex="-1">ESC-03 — Instalación offline en conflicto <a class="header-anchor" href="#esc-03-—-instalacion-offline-en-conflicto" aria-label="Permalink to &quot;ESC-03 — Instalación offline en conflicto&quot;">​</a></h3><p>Una orden se modifica mientras el instalador está sin conexión. Este realizó una intervención y capturó firma/equipo. Al sincronizar se conserva la evidencia y se detecta el conflicto; se decide la situación contractual y financiera con responsabilidad explícita. No se duplica salida de equipo ni se borra lo realizado para igualar estados. <strong>Relacionadas:</strong> AGR-003, 010, 016, 023 y 025.</p><h3 id="esc-04-—-recuperacion-con-operaciones-externas-posteriores-a-la-copia" tabindex="-1">ESC-04 — Recuperación con operaciones externas posteriores a la copia <a class="header-anchor" href="#esc-04-—-recuperacion-con-operaciones-externas-posteriores-a-la-copia" aria-label="Permalink to &quot;ESC-04 — Recuperación con operaciones externas posteriores a la copia&quot;">​</a></h3><p>Se restaura información anterior a una confirmación de pago o emisión fiscal. El sistema recupera y concilia identificadores externos, controla sus efectos y reanuda lo pendiente; no envía otra emisión o cobro por considerar que el registro local faltante nunca existió. <strong>Relacionadas:</strong> AGR-011, 016, 018, 019 y 021.</p><h3 id="esc-05-—-cambio-de-condiciones-en-un-periodo-parcialmente-procesado" tabindex="-1">ESC-05 — Cambio de condiciones en un período parcialmente procesado <a class="header-anchor" href="#esc-05-—-cambio-de-condiciones-en-un-periodo-parcialmente-procesado" aria-label="Permalink to &quot;ESC-05 — Cambio de condiciones en un período parcialmente procesado&quot;">​</a></h3><p>Hay un ciclo con documentos ya emitidos, otros pendientes y una modificación tarifaria propuesta. El sistema mantiene el universo y versiones aplicadas, determina el efecto de vigencia sobre pendientes y conserva una explicación de ajustes. Las promociones y simulaciones no reescriben contratos o documentos por el hecho de volver a ejecutar el lote. <strong>Relacionadas:</strong> AGR-009, 010, 015, 017 y 035.</p><p>Los importes son ficticios y omiten tributos; las correcciones fiscales concretas se validan con el régimen ya previsto en la base.</p><h2 id="_7-orden-recomendado-de-trabajo" tabindex="-1">7. Orden recomendado de trabajo <a class="header-anchor" href="#_7-orden-recomendado-de-trabajo" aria-label="Permalink to &quot;7. Orden recomendado de trabajo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Etapa</th><th>Trabajo concreto</th><th>Salida verificable</th><th>Condición para avanzar</th></tr></thead><tbody><tr><td>A. Consolidación</td><td>Catálogo vigente, alcance final/piloto y decisiones abiertas</td><td>Requisitos y responsables con trazabilidad</td><td>No hay contradicciones bloqueantes sin dueño</td></tr><tr><td>B. Arquitectura funcional</td><td>Identidad, dominios, estados, datos y transacciones</td><td>Mapa de responsabilidades y contratos de interacción</td><td>Se pueden explicar fallos y recuperación del ciclo</td></tr><tr><td>C. Núcleo configurable</td><td>Tenant, seguridad, catálogo, diccionario y publicación</td><td>Dos tenants de prueba con aislamiento y configuración propia</td><td>No se mezclan datos ni se publican condiciones incompletas</td></tr><tr><td>D. Ciclo de servicio piloto</td><td>Contratación, actuación técnica, equipo y activación</td><td>Recorrido extremo a extremo con excepciones</td><td>El estado visible corresponde al hecho real</td></tr><tr><td>E. Circuito económico</td><td>Liquidación, emisión, saldo, cobro, ajustes y conciliación</td><td>Control de integridad y cierre de ciclo</td><td>Dinero y documentos cuadran por contrato/servicio</td></tr><tr><td>F. Preparación operativa</td><td>Migración, carga, seguridad, recuperación y capacitación</td><td>Ensayo de puesta en marcha y acta de aceptación</td><td>Se cumplen los criterios acordados y hay soporte de arranque</td></tr><tr><td>G. Extensión</td><td>Otros dominios, capacidades ERP y evolución</td><td>Incorporación por servicio con su evidencia</td><td>No se copia una regla sin validar su significado y ámbito</td></tr></tbody></table><p>No se asignan semanas, presupuesto, cantidad de desarrolladores ni stack porque no están dimensionados. Las etapas pueden solaparse cuando sus dependencias estén resueltas. El alcance final mantiene los servicios y módulos requeridos; la secuencia evita confundir visión completa con construcción simultánea.</p><h2 id="_8-agenda-de-relevamiento-para-cerrar-los-faltantes" tabindex="-1">8. Agenda de relevamiento para cerrar los faltantes <a class="header-anchor" href="#_8-agenda-de-relevamiento-para-cerrar-los-faltantes" aria-label="Permalink to &quot;8. Agenda de relevamiento para cerrar los faltantes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Responsable a convocar</th><th>Decisiones a resolver</th><th>Material útil</th></tr></thead><tbody><tr><td>Dirección de producto/plataforma</td><td>Alcance SaaS, responsabilidad operativa y entregas</td><td>Acuerdos comerciales y objetivos de servicio</td></tr><tr><td>Administrador del tenant</td><td>Roles/perfiles, configuración y circuitos</td><td>Organigrama, autorizaciones y casos reales</td></tr><tr><td>Comercial/atención</td><td>Contratación, representaciones y excepciones</td><td>Formularios, contratos y reclamos reales anonimizados</td></tr><tr><td>Facturación/contador</td><td>Fechas, reglas, documentos, ajustes y cierres</td><td>Cuadros, comprobantes, conciliaciones y criterios de registración</td></tr><tr><td>Caja/tesorería</td><td>Excedentes, no identificados, devoluciones y fondos</td><td>Rendiciones, extractos y procedimientos de arqueo</td></tr><tr><td>Operación técnica/depósito</td><td>Agenda, equipos, conflictos y devoluciones</td><td>Órdenes, inventario y actuaciones con contingencias</td></tr><tr><td>Secretaría institucional</td><td>Asociación, capital y egreso</td><td>Estatuto, registros y documentación validada</td></tr><tr><td>Soporte/seguridad</td><td>Recuperación, acceso de soporte e incidentes</td><td>Procedimientos y evidencia de pruebas</td></tr><tr><td>Responsables por servicio</td><td>Reglas específicas y documentos regulatorios</td><td>Los insumos ya identificados en la sección 95 de la base</td></tr></tbody></table><h2 id="_9-como-incorporar-estas-propuestas-sin-perder-control-del-alcance" tabindex="-1">9. Cómo incorporar estas propuestas sin perder control del alcance <a class="header-anchor" href="#_9-como-incorporar-estas-propuestas-sin-perder-control-del-alcance" aria-label="Permalink to &quot;9. Cómo incorporar estas propuestas sin perder control del alcance&quot;">​</a></h2><ol><li>Revisar las AGR con los responsables de la cooperativa piloto y del producto.</li><li>Marcar cada propuesta como Aprobada, Ajustar, Diferida o No aplica, con motivo.</li><li>Para las aprobadas, escribir el requisito canónico y sus criterios en la especificación vigente, manteniendo el ID AGR como origen.</li><li>Asignar versión de entrega y dependencia; no convertir P0 en una promesa de entregar todo primero.</li><li>Actualizar modelos de datos, pantallas y pruebas afectados antes de programar el flujo.</li><li>Mantener el anexo de mensajes originales como evidencia y no sobrescribirlo con redacción interpretada.</li></ol><h3 id="plantilla-de-decision" tabindex="-1">Plantilla de decisión <a class="header-anchor" href="#plantilla-de-decision" aria-label="Permalink to &quot;Plantilla de decisión&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Campo</th><th>Contenido a completar</th></tr></thead><tbody><tr><td>Propuesta</td><td>AGR-XXX</td></tr><tr><td>Decisión</td><td>Aprobada / Ajustar / Diferida / No aplica</td></tr><tr><td>Redacción acordada</td><td>Regla precisa y límite</td></tr><tr><td>Responsable</td><td>Rol y persona que valida</td></tr><tr><td>Servicio/tenant</td><td>Ámbito donde aplica</td></tr><tr><td>Dependencias</td><td>Otras decisiones o componentes</td></tr><tr><td>Aceptación</td><td>Ejemplo verificable y evidencia</td></tr><tr><td>Entrega</td><td>Versión o hito acordado</td></tr><tr><td>Fecha y motivo</td><td>Registro de decisión</td></tr></tbody></table><h2 id="_10-referencias-y-limites-de-este-analisis" tabindex="-1">10. Referencias y límites de este análisis <a class="header-anchor" href="#_10-referencias-y-limites-de-este-analisis" aria-label="Permalink to &quot;10. Referencias y límites de este análisis&quot;">​</a></h2><p>La fuente principal es el documento base completo v0.14. Las referencias numéricas de cada AGR permiten ubicar lo ya existente. Este complemento no vuelve a afirmar vigencia de todas las normas de la base ni modifica sus fuentes: la configuración productiva sigue requiriendo los documentos específicos de cada cooperativa.</p><p>Se consultaron tres referencias primarias complementarias el 3 de noviembre de 2026:</p><ul><li><strong>[R1] W3C, WCAG 2.2:</strong> <a href="https://www.w3.org/TR/WCAG22/" target="_blank" rel="noreferrer">https://www.w3.org/TR/WCAG22/</a> — referencia para proponer un objetivo verificable de accesibilidad; no se afirma conformidad del producto.</li><li><strong>[R2] OWASP, Multi-Tenant Security Cheat Sheet:</strong> <a href="https://cheatsheetseries.owasp.org/cheatsheets/Multi_Tenant_Security_Cheat_Sheet.html" target="_blank" rel="noreferrer">https://cheatsheetseries.owasp.org/cheatsheets/Multi_Tenant_Security_Cheat_Sheet.html</a> — referencia de revisión para extender el aislamiento a todos los componentes y probar límites; no impone una implementación concreta de base de datos.</li><li><strong>[R3] IETF, RFC 9457, Problem Details for HTTP APIs:</strong> <a href="https://www.rfc-editor.org/rfc/rfc9457.html" target="_blank" rel="noreferrer">https://www.rfc-editor.org/rfc/rfc9457.html</a> — posible formato uniforme de errores; no es un sustituto del control interno ni una herramienta para publicar detalles sensibles de depuración.</li></ul><p>Las propuestas se apoyan en análisis funcional y diseño del alcance recibido. No se ha inspeccionado el código local de Connectyx, una instalación de ProCoop ni una cooperativa piloto en funcionamiento. Se mantiene la diferencia entre hipótesis de diseño, ejemplos ficticios y decisiones aprobadas.</p><h2 id="_11-control-de-la-revision" tabindex="-1">11. Control de la revisión <a class="header-anchor" href="#_11-control-de-la-revision" aria-label="Permalink to &quot;11. Control de la revisión&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Elemento</th><th>Resultado</th></tr></thead><tbody><tr><td>Base examinada</td><td>Versión 0.14; 96 secciones y 20 mensajes originales</td></tr><tr><td>Extensión de la base</td><td>52,960 palabras, aproximadamente; no es una estimación de esfuerzo</td></tr><tr><td>Propuestas</td><td>36 fichas con trazabilidad, prioridad, ejemplo y aceptación</td></tr><tr><td>P0 / P1 / P2</td><td>17 / 16 / 3</td></tr><tr><td>No explicitado / Detalle insuficiente / Pendiente ya identificado</td><td>2 / 25 / 9</td></tr><tr><td>Documento original</td><td>Conservado sin modificaciones</td></tr><tr><td>Estado del complemento</td><td>Versión 0.1, pendiente de validación</td></tr></tbody></table><p>La priorización ayuda a decidir qué cerrar y cuándo; no implica agregar todos los elementos a un presupuesto o entrega sin validar su necesidad.</p>',283)])])}const m=a(n,[["render",t]]);export{g as __pageData,m as default};
